<?php
declare(strict_types=1);
namespace Modules\Integrations;

final class Details
{
    private static function scalar(mixed $value): string {return is_string($value)||is_int($value)?(string)$value:'';}
    public static function fields(array $row): array {$raw=$row['fields']['record']??$row;$account=$row['fields']['account']??[];$value=$raw['value']??$raw;$mesType=is_array($value)&&isset($value['documentId'])?($value['documentType']??null):null;return ['account_display'=>self::scalar($row['account']??$row['account_number']??$account['number']??$account['DOG_TAG']??$row['account_id']??''),'address'=>self::scalar($row['address']??$row['account_address']??$raw['account_address']??$account['address']??$account['ADR_NAME_FULL']??''),'sender'=>self::scalar($raw['sender']??''),'recipient'=>self::scalar($raw['recipient']??''),'document_type'=>self::scalar($mesType??$raw['type']??$raw['typedNamedId']??$raw['FL_DOC']??''),'bank_payer'=>self::scalar($raw['BankPayer']??''),'bank_organization'=>self::scalar($raw['BankOrganization']??''),'bank_account'=>self::scalar($raw['BankAccount']??''),'bank_purpose'=>self::scalar($raw['НазначениеПлатежа']??$raw['НазначениеПлатежаСтрокой']??''),'bank_operation'=>self::scalar($raw['ВидОперации']??'')];}
    public static function flatten(mixed $value,string $label=''): array {$labels=json_decode(file_get_contents(__DIR__.'/defaults/field-labels.json'),true);$out=[];$walk=function(mixed $v,string $path,int $depth=0)use(&$walk,&$out,$labels){if($depth>24)throw new \RuntimeException('FIELD_DEPTH');if(is_array($v)&&$v){foreach($v as $key=>$item)$walk($item,$path.($path!==''?' → ':'').(is_int($key)?'строка '.($key+1):($labels[$key]??$key)),$depth+1);}else $out[]=['label'=>$path,'value'=>$v===null?'Не указано':($v===true?'Да':($v===false?'Нет':(is_array($v)?'Пусто':(string)$v)))];};$walk($value,$label);return $out;}
    public static function save(\PDO $db,string $id,array $row): void {$f=self::fields($row);$search=implode("\n",array_map(static fn($v)=>$v['label'].' '.$v['value'],self::flatten($row)));$db->prepare('INSERT INTO external_document_details(document_id,account_display,address,sender,recipient,document_type,bank_payer,bank_organization,bank_account,bank_purpose,bank_operation,search_text) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE account_display=VALUES(account_display),address=VALUES(address),sender=VALUES(sender),recipient=VALUES(recipient),document_type=VALUES(document_type),bank_payer=VALUES(bank_payer),bank_organization=VALUES(bank_organization),bank_account=VALUES(bank_account),bank_purpose=VALUES(bank_purpose),bank_operation=VALUES(bank_operation),search_text=VALUES(search_text)')->execute([$id,...array_values($f),$search]);}
    public static function backfill(\PDO $db,PrivateStore $store): int {$rows=$db->query('SELECT d.id,d.raw_path,d.raw_sha256 FROM external_documents d LEFT JOIN external_document_details f ON f.document_id=d.id WHERE f.document_id IS NULL');$count=0;foreach($rows as $r){self::save($db,$r['id'],Support::decode($store->read($r['raw_path'],$r['raw_sha256'])));$count++;}return $count;}
}
